using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
static class OptionChainTests {
 static void Assert(bool condition,string reason){if(!condition)throw new Exception(reason);}
 public static void Run(){var contracts=new List<OptionDescriptor>();for(int strike=22000;strike<=24000;strike+=50){contracts.Add(OptionDescriptor.Parse("TXO"+strike+"J6","20261021",strike,"C"));contracts.Add(OptionDescriptor.Parse("TXO"+strike+"V6","20261021",strike,"P"));}var selected=OptionChain.Select(contracts,22587);Assert(selected.Count==18,"subscription count");Assert(selected.Select(c=>c.Strike).Distinct().Count()==9,"paired strikes");Assert(selected.All(c=>c.Expiry=="2026-10-21"),"metadata expiry");Assert(selected.Any(c=>c.Strike==22600),"ATM included");Assert(selected.All(c=>c.Strike>=22400&&c.Strike<=22800),"nearest strikes");Assert(OptionDescriptor.Parse("TXO22500J6/V6","20261021",22500,"C")==null,"spread excluded");var missing=OptionChain.Select(contracts.Where(c=>c.Side=="call"),22587);Assert(missing.Count==0,"do not fabricate missing put");Assert(OptionDescriptor.Parse("TXX49550V6","",0,"").Side=="put","symbol fallback");var chain=new OptionChain();chain.Plan(selected[0].Group,selected);foreach(var c in selected)chain.Subscription(c.Symbol,true);var call=selected.First(c=>c.Side=="call");var put=selected.First(c=>c.Side=="put");Assert(chain.Book(call.Symbol,100,101,5,6,1000),"quote routed");Assert(chain.Trade(put.Symbol,55.5,7,1200),"option trade routed");Assert(!chain.Trade("TXFJ6",22000,3,1200),"future not claimed");using(var json=JsonDocument.Parse(chain.Json())){var legs=json.RootElement.GetProperty("legs").EnumerateArray().ToArray();var c=legs.First(l=>l.GetProperty("symbol").GetString()==call.Symbol);Assert(c.GetProperty("bid").GetDouble()==100&&c.GetProperty("tradeReceipt").GetInt64()==0,"quote without fake trade");var p=legs.First(l=>l.GetProperty("symbol").GetString()==put.Symbol);Assert(p.GetProperty("volume").GetInt64()==7&&p.GetProperty("last").GetDouble()==55.5,"actual received volume");Assert(!p.TryGetProperty("openInterest",out _),"no fabricated OI");}chain.Subscription(call.Symbol,false);Assert(chain.Json().Contains("API 未接受訂閱"),"API rejection surfaced");Console.WriteLine("PASS: option metadata, 9 paired strikes, subscription limit, quote/trade routing, received volume, missing puts and rejection.");}
}
